mapper.select:
SELECT pi.*, ci.cci_nm AS category_name, pm.mlg_score AS mlg_score FROM public.ncs_prg_info pi LEFT JOIN core_cpt_info ci ON pi.cci_id = ci.cci_id LEFT JOIN public.ncs_prg_mileage pm ON pi.prg_id = pm.prg_id
AND pi.prg_code = #{prgCode} AND pi.cci_id = #{cciId}
ORDER BY pi.prg_id DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE public.ncs_prg_mileage
   SET mlg_score    = #{mileageScore},
       upd_dt       = now(),
       upd_user_id  = #{updUserId}
 WHERE prg_id = #{prgId}
